from collections import defaultdict
from collections import deque

def get_connected_component(grid, start_r, start_c, color):
    """Get connected cells of same color (4-connectivity)."""
    if start_r < 0 or start_r >= len(grid) or start_c < 0 or start_c >= len(grid[0]):
        return set()
    if grid[start_r][start_c] != color:
        return set()

    visited = set()
    queue = deque([(start_r, start_c)])

    while queue:
        r, c = queue.popleft()
        if (r, c) in visited:
            continue
        visited.add((r, c))

        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                if grid[nr][nc] == color and (nr, nc) not in visited:
                    queue.append((nr, nc))

    return visited

