def solve(inp):
    nrows = len(inp)
    ncols = len(inp[0])

    # Start with COPY of input
    out = [row[:] for row in inp]

    # Find solid 3x3 blocks
    blocks = []
    for r in range(nrows-2):
        for c in range(ncols-2):
            val = inp[r][c]
            if val != 0:
                solid = True
                for i in range(3):
                    for j in range(3):
                        if inp[r+i][c+j] != val:
                            solid = False
                            break
                    if not solid:
                        break
                if solid:
                    blocks.append((r, c, val))

    # Write vertical lines first
    for r, c, val in blocks:
        cc = c + 1
        for i in range(nrows):
            out[i][cc] = val

    # Write horizontal lines
    for r, c, val in blocks:
        cr = r + 1
        for j in range(ncols):
            out[cr][j] = val

    # CREATE HOLES LAST (after lines are drawn)
    # Only at intersections of different block lines
    for i, (r1, c1, v1) in enumerate(blocks):
        cr1 = r1 + 1
        cc1 = c1 + 1
        for j, (r2, c2, v2) in enumerate(blocks):
            if i != j:
                # Intersection of horizontal line at cr1 with vertical line at c2+1
                out[cr1][c2+1] = 0
                # Intersection of horizontal line at r2+1 with vertical line at cc1
                out[r2+1][cc1] = 0

    return out

